create table if not exists public.competitions (
  id text primary key,
  slug text not null unique,
  badge text not null default '',
  title text not null default '',
  subtitle text not null default '',
  summary text not null default '',
  description text not null default '',
  location text not null default '',
  season text not null default '',
  image_url text not null default '',
  image_alt text not null default '',
  registration_status text,
  registration_closed_title text,
  registration_closed_text text,
  position_url text,
  documents_route text not null default '/documents',
  sort_order integer not null default 0,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create table if not exists public.competition_stages (
  id text primary key,
  competition_id text not null references public.competitions (id) on delete cascade,
  stage_number integer not null,
  title text not null default '',
  date_label text not null default '',
  stage_date date,
  place text not null default '',
  meta text not null default '',
  description text not null default '',
  status text not null default '',
  protocol_url text not null default '',
  photo_url text not null default '',
  registration_status text,
  registration_open_at timestamptz,
  registration_close_at timestamptz,
  registration_open_date_label text,
  registration_close_date_label text,
  registration_competition_date_label text,
  registration_close_note text,
  registration_closed_title text,
  registration_closed_text text,
  is_public boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  constraint competition_stages_stage_number_check check (stage_number > 0),
  constraint competition_stages_unique_stage_number unique (competition_id, stage_number)
);

create table if not exists public.competition_stage_distances (
  id text primary key,
  stage_id text not null references public.competition_stages (id) on delete cascade,
  distance_label text not null default '',
  stroke_label text not null default '',
  raw_text text not null default '',
  sort_order integer not null default 0
);

create table if not exists public.competition_registration_options (
  id text primary key,
  competition_id text not null references public.competitions (id) on delete cascade,
  option_key text not null default '',
  title text not null default '',
  date_label text not null default '',
  price_label text not null default '',
  action_label text not null default '',
  sort_order integer not null default 0,
  constraint competition_registration_options_unique_key unique (competition_id, option_key)
);

create table if not exists public.competition_faq_sections (
  id text primary key,
  competition_id text not null references public.competitions (id) on delete cascade,
  placement text not null default 'detail',
  title text not null default '',
  sort_order integer not null default 0,
  constraint competition_faq_sections_placement_check check (placement in ('detail', 'registration'))
);

create table if not exists public.competition_faq_items (
  id text primary key,
  section_id text not null references public.competition_faq_sections (id) on delete cascade,
  question text not null default '',
  answer text not null default '',
  sort_order integer not null default 0
);

create or replace function public.touch_competition_catalog_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := timezone('utc', now());
  return new;
end;
$$;

drop trigger if exists competitions_touch_updated_at on public.competitions;
create trigger competitions_touch_updated_at
before update on public.competitions
for each row execute procedure public.touch_competition_catalog_updated_at();

drop trigger if exists competition_stages_touch_updated_at on public.competition_stages;
create trigger competition_stages_touch_updated_at
before update on public.competition_stages
for each row execute procedure public.touch_competition_catalog_updated_at();

create index if not exists competitions_sort_order_idx on public.competitions (sort_order);
create index if not exists competition_stages_competition_sort_idx on public.competition_stages (competition_id, sort_order);
create index if not exists competition_stages_public_idx on public.competition_stages (is_public);
create index if not exists competition_stage_distances_stage_sort_idx on public.competition_stage_distances (stage_id, sort_order);
create index if not exists competition_registration_options_competition_sort_idx on public.competition_registration_options (competition_id, sort_order);
create index if not exists competition_faq_sections_competition_sort_idx on public.competition_faq_sections (competition_id, placement, sort_order);
create index if not exists competition_faq_items_section_sort_idx on public.competition_faq_items (section_id, sort_order);

alter table public.competitions enable row level security;
alter table public.competition_stages enable row level security;
alter table public.competition_stage_distances enable row level security;
alter table public.competition_registration_options enable row level security;
alter table public.competition_faq_sections enable row level security;
alter table public.competition_faq_items enable row level security;

drop policy if exists "Allow public read competitions" on public.competitions;
drop policy if exists "Allow admin write competitions" on public.competitions;
drop policy if exists "Allow public read competition stages" on public.competition_stages;
drop policy if exists "Allow admin write competition stages" on public.competition_stages;
drop policy if exists "Allow public read competition stage distances" on public.competition_stage_distances;
drop policy if exists "Allow admin write competition stage distances" on public.competition_stage_distances;
drop policy if exists "Allow public read competition registration options" on public.competition_registration_options;
drop policy if exists "Allow admin write competition registration options" on public.competition_registration_options;
drop policy if exists "Allow public read competition faq sections" on public.competition_faq_sections;
drop policy if exists "Allow admin write competition faq sections" on public.competition_faq_sections;
drop policy if exists "Allow public read competition faq items" on public.competition_faq_items;
drop policy if exists "Allow admin write competition faq items" on public.competition_faq_items;

create policy "Allow public read competitions" on public.competitions for select to anon, authenticated using (true);
create policy "Allow admin write competitions" on public.competitions for all to authenticated using (public.current_crm_role() = 'admin') with check (public.current_crm_role() = 'admin');
create policy "Allow public read competition stages" on public.competition_stages for select to anon, authenticated using (true);
create policy "Allow admin write competition stages" on public.competition_stages for all to authenticated using (public.current_crm_role() = 'admin') with check (public.current_crm_role() = 'admin');
create policy "Allow public read competition stage distances" on public.competition_stage_distances for select to anon, authenticated using (true);
create policy "Allow admin write competition stage distances" on public.competition_stage_distances for all to authenticated using (public.current_crm_role() = 'admin') with check (public.current_crm_role() = 'admin');
create policy "Allow public read competition registration options" on public.competition_registration_options for select to anon, authenticated using (true);
create policy "Allow admin write competition registration options" on public.competition_registration_options for all to authenticated using (public.current_crm_role() = 'admin') with check (public.current_crm_role() = 'admin');
create policy "Allow public read competition faq sections" on public.competition_faq_sections for select to anon, authenticated using (true);
create policy "Allow admin write competition faq sections" on public.competition_faq_sections for all to authenticated using (public.current_crm_role() = 'admin') with check (public.current_crm_role() = 'admin');
create policy "Allow public read competition faq items" on public.competition_faq_items for select to anon, authenticated using (true);
create policy "Allow admin write competition faq items" on public.competition_faq_items for all to authenticated using (public.current_crm_role() = 'admin') with check (public.current_crm_role() = 'admin');

with source_catalog as (
  select $catalog$[{"slug":"smartswimcup","badge":"Основная серия","title":"SmartSwimCup","subtitle":"Участники 2007 - 2017 г.р.","summary":"Этапы с присвоением разрядов, подробной программой дистанций и понятным циклом подготовки в течение сезона.","description":"Серия для тех, кто уже готов к регулярным стартам: понятный ритм сезона, аккуратная организация, разрядные дистанции и прозрачная логика участия от этапа к этапу.","location":"г. Красногорск,\nул. Советская, 15","season":"Сезон 2026","registration":{"positionUrl":"/uploads/competitions/SmartSwim2026.pdf","documentsRoute":"/documents","options":[{"id":"distances-1-2","title":"Регистрация участника на 1-2 дистанции","dateLabel":"24 мая","priceLabel":"2000 р.","actionLabel":"Регистрация"},{"id":"distances-3","title":"Регистрация участника на 3 дистанции","dateLabel":"24 мая","priceLabel":"2600 р.","actionLabel":"Регистрация"}],"faqSections":[{"title":"","items":[{"question":"Как подать заявку на соревнования?","answer":"Прием заявок начинается за двадцать один день до старта предстоящего этапа. Заявки подаются как лично, так и на группу ( по адресу cupsmartswim@yandex.ru). Для допуска на соревнование необходимо прикрепить/направить документы:\n\n- паспорт или свидетельство о рождении;\n- Медицинскую заявку, заверенную печатью физкультурного диспансера и подписью врача, подписью представителя команды или медицинскую справку о допуске к соревнованиям, подписанную врачом по лечебной физкультуре или врачом по спортивной медицине и заверенная печатью медицинской организации, если спортсмен заявлен лично;\n- Действующий страховой полис на спортсмена, покрывающий события, которые могут возникнуть при участии в соревнованиях по плаванию;\n- Согласие на обработку персональных данных спортсмена для соревнований. Скачать можно в разделе ДОКУМЕНТЫ.\n\nДокументы для допуска на соревнование, можно дослать на почту CupSmartSwim@yandex.ru не позднее 2х дней до начала соревнований."},{"question":"Личное участие","answer":"- Выбрать количество дистанций.\n- Заполнить форму регистрации.\n- Загрузить в форму регистрации документы для допуска на соревнование.\n- Оплатить.\n- Секретарь Вам ответит на указанный Вами email в течение 72 часов.\n\nВ случае отсутствия документа(ов) для допуска на соревнование, можно дослать на почту cupsmartswim@yandex.ru"},{"question":"Групповое участие","answer":"- Заполнить заявку. ЗАЯВКА ПРИНИМАЕТСЯ ТОЛЬКО В ФОРМАТЕ WORD.\n- Загрузить заявку и весь пакет документов для допуска на соревнование на каждого спортсмена, форму регистрации заявку, в формате WORD, и документы, и отправить на почту CupSmartSwim@yandex.ru\n- В ответ Вам придет информация от секретаря соревнований и ссылка на оплату. Оплатить нужно не позднее чем 24 часа с момента получения ответа."},{"question":"Эстафетное плавание","answer":"Для предварительной заявки необходимо заполнить\n- Название команды - поле СПОРТКЛУБ\n- Заявочное время\n- Email\n- Телефон\n\nВозрастные группы спортсменов в эстафете Кубок SmartSwim :\n- 2013- 2010 г.р.\n- 2009 - 2004 г.р.\n\nВ составе эстафеты должно быть 2 девушки и 2 юноши.\n\nВ Смартиках:\n- Ребенок + взрослый 18+ (мама/папа/брат/сестра)\n\nБланк заявки с фамилиями спортсмена подаётся в секретариат не позднее начала соревнований/ сессии.\n\nТелефон\n\nРегламент проведения комбинированной смешанной эстафеты 4 по 50 м:\n\nЧетыре участника команды поочерёдно плывут дистанцию разным стилем.\nПорядок комбинированной эстафеты:\n- 50 м на спине\n- 50 м брасс\n- 50 м баттерфляй\n- 50 м вольный стиль"},{"question":"Как и когда осуществляется проход зрителей?","answer":"Через отдельный вход на трибуну за 5 минут до начала соревнований , строго в сменной обуви."},{"question":"Если не проходит оплата?","answer":"Нужно очистить кеш браузера, если не помогло, то отправьте заявку на CupSmartSwim@yandex.ru и в теме напишите, что оплата не прошла\n\nИли же Вы можете оплатить по QR коду и на почту CupSmartSwim@yandex.ru отправить все данные и файлы и чек об оплате\n\nQR код:\nhttps://smartswim.ru/images/qr.png"}]}]},"image":"/images/04-img.webp","imageAlt":"Пловец на старте соревнований","cards":[{"title":"IV","date":"26 апреля 2026","place":"","meta":"Разрядный этап","description":"50 м брасс, 100 м вольный стиль, 200 м брасс, 100 м на спине, 100 м комплексное плавание, 400 м вольный стиль.","status":"Этап сезона","registration":{"status":"closed","closedTitle":"Регистрация закрыта","closedText":"Регистрация на этап уже завершена.","competitionDateLabel":"26 апреля 2026"}},{"title":"V","date":"24 мая 2026","place":"","meta":"Весенний финал блока","description":"200 м комплексное плавание, 50 м баттерфляй, 50 м на спине, 50 м брасс, 50 м вольный стиль, 100 м комплексное плавание.","status":"Этап сезона","registration":{"status":"closed","competitionDateLabel":"24 мая 2026","closedTitle":"Регистрация закрыта","closedText":"Регистрация на этот этап уже завершена."}},{"title":"VI","date":"27 сентября 2026","place":"","meta":"Возвращение после летнего цикла","description":"100 м вольный стиль, 50 м баттерфляй, 50 м на спине, 50 м брасс, 50 м вольный стиль, 100 м комплексное плавание.","status":"Этап сезона","registration":{"status":"closed","closedTitle":"Регистрация закрыта","closedText":"Регистрация на этот этап еще не опубликована.","competitionDateLabel":"27 сентября 2026"}},{"title":"VII","date":"25 октября 2026","place":"","meta":"","description":"50 м вольный стиль, 50 м баттерфляй, 100 м на спине, 50 м брасс, 100 м комплексное плавание, 200 м вольный стиль.","status":"Этап сезона","registration":{"status":"upcoming","openAt":"2026-10-04T00:00:00+03:00","closeAt":"2026-10-22T23:59:59+03:00","openDateLabel":"04.10.2026","competitionDateLabel":"25 октября 2026","closeNote":"Регистрация закрывается за 3 дня или по достижению лимита мест"}},{"title":"VIII","date":"22 ноября 2026","place":"","meta":"Объемные дистанции","description":"50 м на спине, 100 м баттерфляй, 100 м вольный стиль, 100 м брасс, 200 м на спине, 400 м вольный стиль.","status":"Этап сезона","registration":{"status":"upcoming","openAt":"2026-11-01T00:00:00+03:00","closeAt":"2026-11-19T23:59:59+03:00","openDateLabel":"01.11.2026","competitionDateLabel":"22 ноября 2026","closeNote":"Регистрация закрывается за 3 дня или по достижению лимита мест"}},{"title":"IX","date":"20 декабря 2026","place":"","meta":"Финал года","description":"50 м вольный стиль, 50 м брасс, 50 м на спине, 100 м комплексное плавание, 200 м брасс, 200 м вольный стиль, 200 м комплексное плавание.","status":"Финальный этап сезона","registration":{"status":"upcoming","openAt":"2026-11-29T00:00:00+03:00","closeAt":"2026-12-17T23:59:59+03:00","openDateLabel":"29.11.2026","competitionDateLabel":"20 декабря 2026","closeNote":"Регистрация закрывается за 3 дня или по достижению лимита мест"}}],"faqSections":[{"items":[{"question":"Как подать заявку на соревнования?","answer":"Прием заявок начинается за двадцать один день до старта предстоящего этапа.\n\nЗаявки подаются как лично, так и на группу по адресу cupsmartswim@yandex.ru.\n\nДля допуска на соревнование необходимо прикрепить/направить документы:\n- паспорт или свидетельство о рождении;\n- медицинскую заявку, заверенную печатью физкультурного диспансера и подписью врача, подписью представителя команды или медицинскую справку о допуске к соревнованиям, подписанную врачом по лечебной физкультуре или врачом по спортивной медицине и заверенную печатью медицинской организации, если спортсмен заявлен лично;\n- действующий страховой полис на спортсмена, покрывающий события, которые могут возникнуть при участии в соревнованиях по плаванию;\n- согласие на обработку персональных данных спортсмена для соревнований.\n\nДокументы для допуска на соревнование можно дослать на почту cupsmartswim@yandex.ru не позднее 2 дней до начала соревнований."},{"question":"Можно скорректировать заявку после ее принятия?","answer":"Изменение данных возможно до окончания приема заявок, т.е. за 7 (семь) дней до начала соревнования."},{"question":"Когда и как осуществляется проход участников на соревнования?","answer":"Проход на соревнования осуществляется за 15 минут до начала разминки, согласно положению соревнований.\nВремя может быть изменено.\n\nПроход участников на соревнование осуществляется при предъявлении только оригинала медицинской заявки/медицинской справки или копии справки из диспансера и согласия на обработку персональных данных."},{"question":"Как и когда осуществляется проход зрителей?","answer":"Через отдельный вход на трибуну за 5 минут до начала соревнований, строго в сменной обуви."},{"question":"Мой ребенок первый раз принимает участие в соревнованиях у Вас, расскажите, что ему надо знать?","answer":"Если спортсмен впервые принимает участие в соревнованиях, а также чтобы не пропустить свой заплыв, следует:\n- заранее ознакомиться и найти себя в стартовом протоколе, в котором указан номер заплыва и дорожки. Протокол также размещается в местах проведения соревнования;\n- на соревновании найти место формирования заплывов, которое находится сразу при выходе с трибуны;\n- на месте формирования заплывов следовать указаниям судьи, который вызывает участников на заплыв;\n- в случае пропуска своего заплыва участнику можно обратиться к судьям или в секретариат.\n\nГлавное! Одной из целей соревнования является приобретение спортсменами соревновательного опыта, а также повышение спортивного мастерства.\nВ случае неудачи, а неудачи бывают у всех, разрушенных надежд, невыполнения разряда и тому подобного, важно сделать анализ над ошибками и работать дальше."},{"question":"Где оставить ценные вещи?","answer":"Организаторы соревнования и администрация спортивного комплекса не несут ответственности за ценные вещи,\nпоэтому мы советуем оставить у представителя участника соревнования то, чем вы дорожите."},{"question":"Если спортсмен заявлен вольным стилем, можно проплыть другим стилем плавания?","answer":"На дистанциях вольным стилем пловцу разрешается плыть любыми способами."},{"question":"Если в Программе соревнования есть дистанция, например 50 м вольный стиль, участник проплыл, например, на спине и выполнил разряд, ему присвоят разряд в соответствии с нормативами на спине?","answer":"Нет.\n\nРазряд будет присвоен в соответствии с Программой соревнования, т.е. в соответствии с нормативами вольного стиля."}]},{"items":[{"question":"Есть оригинал справки (мед допуска) хранится в спортшколе, можно принести копию?","answer":"Можно.\n\nТолько если справка с QR-кодом."},{"question":"Как выглядит справка для участия в соревнованиях и что в ней должно быть указано?","answer":"Примеры справок: если лично, справка для личного участия; если из спортшколы, справка СШ.\n\nДля детей, участвующих в Кубке Smart Swim, обязательно должен быть допуск к соревнованиям.\nДля участия в Смартиках достаточно справки от педиатра для посещения бассейна."},{"question":"Где и когда можно посмотреть Положение, Регламент о соревнованиях, Заявочный, Стартовый и Итоговый протоколы?","answer":"Всю информацию можно найти на странице этапа соревнования.\n\n- заявочный протокол публикуется за 3 (три) дня до начала соревнования;\n- стартовый протокол публикуется за 8 (восемь) часов до начала соревнования;\n- итоговый протокол публикуется после окончания соревнования в этот же день;\n- общие итоговые протоколы можно посмотреть в разделе прошедших соревнований."},{"question":"Если спортсмен выполнил разряд, где и когда он может получить документы для присвоения разряда?","answer":"Вы можете получить документы у секретаря в день соревнований или на любом следующем этапе."}]},{"items":[{"question":"Можно ли сделать возврат стартового взноса?","answer":"Да, можно.\n\nНе позднее 72 часов до начала соревнований.\n\nНеобходимо направить информацию на электронную почту cupsmartswim@yandex.ru и приложить:\n- заявление на возврат;\n- скан паспорта (2-я страница с разворотом).\n\nСумма возврата стартового взноса осуществляется за вычетом понесенных расходов организатором.\nВозврат осуществляется в течение 30 дней с момента подачи заявления."},{"question":"Можно ли перенести стартовый взнос на следующий этап?","answer":"Да, можно.\n\nСтартовый взнос можно перенести на другую дату соревнования не позднее публикации заявочного протокола.\nСтартовый взнос должен быть реализован в период действия текущего Положения / Регламента.\n\nПеренести можно 1 (один) раз."}]}]},{"slug":"smartiki","badge":"Соревнования по плаванию","title":"Smartiki 2026","subtitle":"2019 г.р. и младше","summary":"Календарь соревнований на 2026 год.","description":"Презентация кубка smartiki","location":"ул. Советская, 15","season":"Сезон 2026","registration":{"status":"closed","closedTitle":"Регистрация закрыта","closedText":"Регистрация на этот этап еще не опубликована.","positionUrl":"/uploads/competitions/ПоложениеСмартики2026.pdf?v=20260423","documentsRoute":"/documents","options":[{"id":"distances-1-2","title":"Регистрация участника на 1-2 дистанции","dateLabel":"24 мая","priceLabel":"2000 р.","actionLabel":"Регистрация"},{"id":"distances-3","title":"Регистрация участника на 3 дистанции","dateLabel":"24 мая","priceLabel":"2600 р.","actionLabel":"Регистрация"}],"faqSections":[{"title":"","items":[{"question":"Как подать заявку на соревнования?","answer":"Прием заявок начинается за двадцать один день до старта предстоящего этапа. Заявки подаются как лично, так и на группу ( по адресу cupsmartswim@yandex.ru). Для допуска на соревнование необходимо прикрепить/направить документы:\n\n- паспорт или свидетельство о рождении;\n- Медицинскую заявку, заверенную печатью физкультурного диспансера и подписью врача, подписью представителя команды или медицинскую справку о допуске к соревнованиям, подписанную врачом по лечебной физкультуре или врачом по спортивной медицине и заверенная печатью медицинской организации, если спортсмен заявлен лично;\n- Действующий страховой полис на спортсмена, покрывающий события, которые могут возникнуть при участии в соревнованиях по плаванию;\n- Согласие на обработку персональных данных спортсмена для соревнований. Скачать можно в разделе ДОКУМЕНТЫ.\n\nДокументы для допуска на соревнование, можно дослать на почту CupSmartSwim@yandex.ru не позднее 2х дней до начала соревнований."},{"question":"Личное участие","answer":"- Выбрать количество дистанций.\n- Заполнить форму регистрации.\n- Загрузить в форму регистрации документы для допуска на соревнование.\n- Оплатить.\n- Секретарь Вам ответит на указанный Вами email в течение 72 часов.\n\nВ случае отсутствия документа(ов) для допуска на соревнование, можно дослать на почту cupsmartswim@yandex.ru"},{"question":"Групповое участие","answer":"- Заполнить заявку. ЗАЯВКА ПРИНИМАЕТСЯ ТОЛЬКО В ФОРМАТЕ WORD.\n- Загрузить заявку и весь пакет документов для допуска на соревнование на каждого спортсмена, форму регистрации заявку, в формате WORD, и документы, и отправить на почту CupSmartSwim@yandex.ru\n- В ответ Вам придет информация от секретаря соревнований и ссылка на оплату. Оплатить нужно не позднее чем 24 часа с момента получения ответа."},{"question":"Эстафетное плавание","answer":"Для предварительной заявки необходимо заполнить\n- Название команды - поле СПОРТКЛУБ\n- Заявочное время\n- Email\n- Телефон\n\nВозрастные группы спортсменов в эстафете Кубок SmartSwim :\n- 2013- 2010 г.р.\n- 2009 - 2004 г.р.\n\nВ составе эстафеты должно быть 2 девушки и 2 юноши.\n\nВ Смартиках:\n- Ребенок + взрослый 18+ (мама/папа/брат/сестра)\n\nБланк заявки с фамилиями спортсмена подаётся в секретариат не позднее начала соревнований/ сессии.\n\nТелефон\n\nРегламент проведения комбинированной смешанной эстафеты 4 по 50 м:\n\nЧетыре участника команды поочерёдно плывут дистанцию разным стилем.\nПорядок комбинированной эстафеты:\n- 50 м на спине\n- 50 м брасс\n- 50 м баттерфляй\n- 50 м вольный стиль"},{"question":"Как и когда осуществляется проход зрителей?","answer":"Через отдельный вход на трибуну за 5 минут до начала соревнований , строго в сменной обуви."},{"question":"Если не проходит оплата?","answer":"Нужно очистить кеш браузера, если не помогло, то отправьте заявку на CupSmartSwim@yandex.ru и в теме напишите, что оплата не прошла\n\nИли же Вы можете оплатить по QR коду и на почту CupSmartSwim@yandex.ru отправить все данные и файлы и чек об оплате\n\nQR код:\nhttps://smartswim.ru/images/qr.png"}]}]},"image":"/images/05-img.webp","imageAlt":"Юные спортсмены в бассейне","cards":[{"title":"IV","date":"26 апреля 2026","place":"","meta":"","description":"25 м вольный стиль, 50 м брасс, 50 м на спине, 50 м вольный стиль, 400 м вольный стиль.","status":"Этап сезона"},{"title":"V","date":"24 мая 2026","place":"","meta":"","description":"25 м вольный стиль, 25 м брасс, 25 м баттерфляй, 50 м на спине, 50 м вольный стиль.","status":"Этап сезона","registration":{"status":"upcoming","openAt":"2026-05-03T00:00:00+03:00","closeAt":"2026-05-21T23:59:59+03:00","openDateLabel":"03.05.2026","competitionDateLabel":"24 мая 2026","closeNote":"Регистрация закрывается за 3 дня или по достижению лимита мест"}},{"title":"VI","date":"27 сентября 2026","place":"","meta":"","description":"25 м на спине, 25 м брасс, 25 м вольный стиль, 50 м вольный стиль.","status":"Этап сезона","registration":{"status":"upcoming","openAt":"2026-09-06T00:00:00+03:00","closeAt":"2026-09-24T23:59:59+03:00","openDateLabel":"06.09.2026","competitionDateLabel":"27 сентября 2026","closeNote":"Регистрация закрывается за 3 дня или по достижению лимита мест"}},{"title":"VII","date":"25 октября 2026","place":"","meta":"","description":"25 м вольный стиль, 25 м баттерфляй, 50 м на спине, 50 м вольный стиль.","status":"Этап сезона","registration":{"status":"upcoming","openAt":"2026-10-04T00:00:00+03:00","closeAt":"2026-10-22T23:59:59+03:00","openDateLabel":"04.10.2026","competitionDateLabel":"25 октября 2026","closeNote":"Регистрация закрывается за 3 дня или по достижению лимита мест"}},{"title":"VIII","date":"22 ноября 2026","place":"","meta":"","description":"25 м на спине, 25 м брасс, 50 м на спине, 50 м вольный стиль.","status":"Этап сезона","registration":{"status":"upcoming","openAt":"2026-11-01T00:00:00+03:00","closeAt":"2026-11-19T23:59:59+03:00","openDateLabel":"01.11.2026","competitionDateLabel":"22 ноября 2026","closeNote":"Регистрация закрывается за 3 дня или по достижению лимита мест"}},{"title":"IX","date":"20 декабря 2026","place":"","meta":"","description":"25 м на спине, 25 м вольный стиль, 50 м на спине, 50 м брасс, 50 м вольный стиль.","status":"Финальный этап сезона","registration":{"status":"upcoming","openAt":"2026-11-29T00:00:00+03:00","closeAt":"2026-12-17T23:59:59+03:00","openDateLabel":"29.11.2026","competitionDateLabel":"20 декабря 2026","closeNote":"Регистрация закрывается за 3 дня или по достижению лимита мест"}}],"faqSections":[{"title":"Общие вопросы","items":[{"question":"Как подать заявку на соревнования?","answer":"Прием заявок начинается за двадцать один день до старта предстоящего этапа.\n\nЗаявки подаются как лично, так и на группу (по адресу cupsmartswim@yandex.ru).\n\nДля допуска на соревнование необходимо прикрепить/направить документы:\n- паспорт или свидетельство о рождении;\n- медицинскую заявку, заверенную печатью физкультурного диспансера и подписью врача, подписью представителя команды или медицинскую справку о допуске к соревнованиям, подписанную врачом по лечебной физкультуре или врачом по спортивной медицине и заверенную печатью медицинской организации, если спортсмен заявлен лично;\n- действующий страховой полис на спортсмена, покрывающий события, которые могут возникнуть при участии в соревнованиях по плаванию;\n- согласие на обработку персональных данных спортсмена для соревнований.\n\nДокументы для допуска на соревнование можно дослать на почту cupsmartswim@yandex.ru не позднее 2х дней до начала соревнований."},{"question":"Можно скорректировать заявку после ее принятия?","answer":"Изменение данных возможно до окончания приема заявок,\nт.е. за 7 (семь) дней до начала соревнования."},{"question":"Когда и как осуществляется проход участников на соревнования?","answer":"Проход на соревнования осуществляется за 15 минут до начала разминки, согласно положению соревнований.\nВремя может быть изменено.\n\nПроход участников на соревнование осуществляется при предъявлении ТОЛЬКО ОРИГИНАЛА медицинской заявки/медицинскую справку или КОПИЮ справки из диспансера и Согласии на обработку персональных данных."},{"question":"Как и когда осуществляется проход зрителей?","answer":"Через отдельный вход на трибуну за 5 минут до начала соревнований ,\nстрого в сменной обуви."},{"question":"Мой ребенок первый раз принимает участие в соревнованиях у Вас, расскажите, что ему надо знать?","answer":"Если спортсмен впервые принимает участие в соревнованиях, а также, чтобы не пропустить свой заплыв, следует:\n- Заранее ознакомиться и найти себя в Стартовом протоколе, в котором указан номер заплыва и дорожки. Протокол также размещается в местах проведения Соревнования;\n- На Соревновании найти место формирование заплывов, которое находится сразу при выходе с трибуны;\n- На месте формирования заплывов следовать указаниям Судьи, который вызывает участников на заплыв.\n- В случае пропуска своего заплыва участнику может обратиться к Судьям или в секретариат.\n\nГлавное! Одной из целью Соревнования является приобретение спортсменами соревновательного опыта, а также повышение спортивного мастерства. В случае неудачи, а неудачи бывают у всех, разрушенных надежд, невыполнения разряда и тому подобное, сделать анализ над ошибками и работать дальше.\n\nПЛАВАНИЕ ЛЮБИТ ЦЕЛЕУСТРЕМЛЕННЫХ!"},{"question":"Где оставить ценные вещи?","answer":"Организаторы Соревнования и администрация спортивного комплекса не несут ответственности за ценные вещи, поэтому мы советуем оставить у представителя участника соревнования, то чем вы дорожите."},{"question":"Если спортсмен заявлен вольным стилем, можно проплыть другим стилем плавания?","answer":"На дистанциях вольным стилем пловцу разрешается плыть любыми способами."},{"question":"Если в Программе соревнования есть дистанция, например 50 м вольный стиль, участник проплыл, например, на спине и выполнил разряд, ему присвоят разряд в соответствии с нормативами на спине?","answer":"Нет.\n\nРазряд будет присвоен в соответствии с Программой соревнования, т.е. в соответствии с нормативами вольного стиля."}]},{"title":"Документы. Протоколы. Разряд.","items":[{"question":"Есть оригинал справки (мед допуска) хранится в спортшколе, можно принести копию?","answer":"Можно.\n\nТолько если справка с QR-кодом."},{"question":"Как выглядит справка для участия в соревнованиях и что в ней должно быть указано?","answer":"Примеры справок: если лично, Справка, если из спортшколы, Справка СШ. Для детей , участвующих в Кубке Smart Swim обязательно должен быть допуск к соревнованиям.\nДля участия в Смартиках достаточно справки от педиатра для посещения бассейна."},{"question":"Где и когда можно посмотреть Положение, Регламент о соревнованиях, Заявочный, Стартовый и Итоговый протоколы?","answer":"Всю информацию можно найти на этапе соревнования странице Соревнования SmartSwimCup\n- Заявочный протокол публикуется за 3 (три) дня до начала соревнования.\n- Стартовый протокол публикуется за 8 (восемь) часов до начала соревнования.\n- Итоговый протокол публикуется после окончания соревнования в этот же день. Общие\n- Общие итоговые протоколы можно посмотреть в разделе Прошедшие соревнования"},{"question":"Если спортсмен выполнил разряд, где и когда он может получить документы для присвоения разряда?","answer":"Вы можете получить документы у секретаря в день соревнований или на любом следующем этапе."}]},{"title":"Оплата. Сроки. Возврат.","items":[{"question":"Можно сделать возврат Стартового взноса?","answer":"Да, можно. Не позднее 72 часов до начала соревнований.\n\nНеобходимо направить информацию на электронную почту CupSmartSwim@yandex.ru и приложить:\n\n- Заявление на возврат;\n- Скан паспорта (2-я страница с разворотом);\n\nСумма возврата стартового взноса осуществляется за вычетом понесенных расходов организатором. Возврат осуществляется в течении 30 дней с момента подачи заявления."},{"question":"Можно перенести Стартовый взнос на следующее Соревнование ?","answer":"Да, можно.\n\nСтартовый взнос можно перенести на другую дату соревнования не позднее публикации Заявочного протокола. Стартовый взнос должен быть реализован в период действующего текущего Положения / Регламента.\n\nПеренести можно 1 (один) раз."}]}]}]$catalog$::jsonb as data
), competition_rows as (
  select
    item.value as item,
    item.ordinality::integer as sort_order,
    item.value ->> 'slug' as competition_id
  from source_catalog,
  jsonb_array_elements(data) with ordinality as item(value, ordinality)
)
insert into public.competitions (
  id,
  slug,
  badge,
  title,
  subtitle,
  summary,
  description,
  location,
  season,
  image_url,
  image_alt,
  registration_status,
  registration_closed_title,
  registration_closed_text,
  position_url,
  documents_route,
  sort_order
)
select
  competition_id,
  competition_id,
  coalesce(item ->> 'badge', ''),
  coalesce(item ->> 'title', ''),
  coalesce(item ->> 'subtitle', ''),
  coalesce(item ->> 'summary', ''),
  coalesce(item ->> 'description', ''),
  coalesce(item ->> 'location', ''),
  coalesce(item ->> 'season', ''),
  coalesce(item ->> 'image', ''),
  coalesce(item ->> 'imageAlt', ''),
  item #>> '{registration,status}',
  item #>> '{registration,closedTitle}',
  item #>> '{registration,closedText}',
  item #>> '{registration,positionUrl}',
  coalesce(item #>> '{registration,documentsRoute}', '/documents'),
  sort_order
from competition_rows
on conflict (id) do update
set
  badge = excluded.badge,
  title = excluded.title,
  subtitle = excluded.subtitle,
  summary = excluded.summary,
  description = excluded.description,
